<template>
  <div class="education-workbench">
    <header class="page-header">
      <div><span class="eyebrow">SAFETY EDUCATION</span><h1>安全教育工作台</h1><p>从本期风险出发，找到学习资料，跟进培训执行。</p></div>
      <el-button text :loading="overviewLoading" @click="refresh">刷新数据</el-button>
    </header>

    <section class="overview-panel" aria-label="本周安全教育概览">
      <div class="overview-heading"><div><span class="section-kicker">本周安全教育概览</span><h2>{{ weekLabel }}</h2></div><span class="overview-source">现场事件 · 学习任务</span></div>
      <div class="metric-grid">
        <div class="metric"><span>违规事件</span><strong>{{ overview?.total_events ?? '—' }}</strong><small>本周有效事件</small></div>
        <div class="metric critical"><span>高风险事件</span><strong>{{ overview?.high_risk_events ?? '—' }}</strong><small>严重级别事件</small></div>
        <div class="metric"><span>已生成培训</span><strong>{{ overview?.training_count ?? '—' }}</strong><small>本周创建任务</small></div>
        <div class="metric progress"><span>培训完成率</span><strong>{{ overview ? `${overview.completion_rate}%` : '—' }}</strong><small>{{ overview ? `${overview.completed_count} / ${overview.target_count} 人次` : '已发布任务口径' }}</small></div>
      </div>
      <div class="overview-footer"><div class="risk-line"><span>主要风险</span><template v-if="overview?.main_risks.length"><span v-for="risk in overview.main_risks" :key="risk.code" class="risk-chip">{{ risk.label }} <b>{{ risk.count }}</b></span></template><span v-else class="muted">本周暂无有效违规事件</span></div><div class="hero-actions"><el-button plain @click="reportFormOpen = true">自定义报告时间</el-button><el-button type="primary" :loading="busy" @click="makeWeeklyReport">AI 生成本周安全报告</el-button><el-button color="#6959d5" plain @click="openTrainingComposer()">生成培训方案</el-button></div></div>
      <p v-if="overviewError" class="inline-error">本周概览暂时无法更新，报告和资料仍可继续使用。<button @click="loadOverview">重试</button></p>
    </section>

    <div class="content-grid">
      <main class="primary-column">
        <section class="surface recommended-section">
          <div class="section-head"><div><span class="section-kicker">基于本周风险</span><h2>推荐事故案例</h2></div><span class="small-note">依据事故报告语义检索</span></div>
          <div v-if="currentInsights?.recommended_cases.length" class="recommend-grid">
            <article v-for="(doc, index) in currentInsights.recommended_cases" :key="doc.document_id" class="recommend-card">
              <div class="recommend-index">{{ String(index + 1).padStart(2, '0') }}</div>
              <div class="recommend-body"><div class="card-top"><span class="type-pill">事故案例</span><time>{{ doc.document_date ? formatDay(doc.document_date) : '日期未注明' }}</time></div><h3>{{ doc.title }}</h3><p class="summary">{{ doc.summary || '暂无摘要，可在详情中生成。' }}</p><div class="related"><span>关联本周风险</span><b v-for="risk in doc.related_risks" :key="risk">{{ risk }}</b></div><div class="card-actions"><el-button link type="primary" @click="openDocument(doc)">查看详情</el-button><el-button link @click="addToTraining(doc)">加入培训 +</el-button></div></div>
            </article>
          </div>
          <div v-else class="empty-state"><strong>{{ insightsLoading ? '正在检索相关案例…' : '暂无可推荐案例' }}</strong><p v-if="!insightsLoading">{{ overview?.main_risks.length ? '请确认事故报告已索引，或在下方上传相关案例。' : '本周暂无有效风险数据，仍可从案例库中选择学习资料。' }}</p></div>
        </section>

        <section class="surface library-section">
          <div class="section-head"><div><span class="section-kicker">资料检索</span><h2>事故案例库 <small>· {{ documentTotal }} 份</small></h2></div><el-button type="primary" plain @click="uploadOpen = true">上传文档</el-button></div>
          <div class="filter-row"><el-input v-model="docQuery" placeholder="搜索标题、摘要或正文" clearable @keyup.enter="loadDocuments" /><el-select v-model="docType" aria-label="资料类型"><el-option label="事故案例" value="ACCIDENT_REPORT" /><el-option label="规范文档" value="STANDARD" /></el-select><el-select v-model="riskType" placeholder="风险类型" clearable filterable><el-option v-for="tag in availableRiskTags" :key="tag" :label="tag" :value="tag" /></el-select><el-date-picker v-model="documentRange" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" clearable /><el-button @click="searchLibrary">筛选</el-button></div>
          <div v-if="documents.length" class="library-grid"><button v-for="doc in documents" :key="doc.document_id" class="library-card" @click="openDocument(doc)"><span class="library-type">{{ doc.document_type === 'STANDARD' ? '规范资料' : '事故案例' }} <time>{{ doc.document_date ? formatDay(doc.document_date) : '未注明日期' }}</time></span><strong>{{ doc.title }}</strong><span class="library-summary">{{ doc.summary || '暂无摘要，点击查看原文资料。' }}</span><span class="library-foot">{{ doc.risk_tags.slice(0, 2).join(' · ') || '未标注风险' }} <i>查看 ↗</i></span></button></div>
          <div v-else class="empty-state"><strong>没有匹配的资料</strong><p>试试其他关键词或筛选条件，也可以上传新文档。</p></div>
          <el-pagination v-if="documentTotal > 20" class="pagination" layout="prev, pager, next" :total="documentTotal" :page-size="20" :current-page="documentOffset / 20 + 1" @current-change="changeDocumentPage" />
        </section>
      </main>

      <aside class="side-column">
        <section class="surface task-section"><div class="section-head"><div><span class="section-kicker">培训执行</span><h2>本周培训任务</h2></div><el-button link @click="openTrainingComposer()">新建 +</el-button></div>
          <div v-if="weeklyTraining.length" class="weekly-task-list"><button v-for="task in weeklyTraining" :key="task.task_id" class="weekly-task" @click="showTraining(task)"><span class="task-top"><b>{{ task.title }}</b><span :class="task.status === 'PUBLISHED' ? 'status-running' : 'status-draft'">{{ task.status === 'PUBLISHED' ? '进行中' : '待发布' }}</span></span><span class="task-count">参与目标 {{ task.target_count }} 人 · 已完成 {{ task.weekly?.completed_count ?? 0 }} 人</span><el-progress :percentage="task.target_count ? Math.min(100, Math.round(100 * (task.weekly?.completed_count ?? 0) / task.target_count)) : 0" :stroke-width="6" :show-text="false" /><span class="task-bottom">平均分 {{ task.weekly?.average_score ?? 0 }} <i>查看详情 ↗</i></span></button></div>
          <div v-else class="empty-state compact"><strong>本周尚无培训任务</strong><p>从本周风险和推荐案例创建培训方案。</p><el-button type="primary" plain @click="openTrainingComposer()">生成培训</el-button></div>
        </section>
        <section class="advice-panel"><span class="advice-icon">✦</span><span class="section-kicker">AGENT INSIGHT</span><h2>AI 教育建议</h2><p v-if="currentInsights?.advice">{{ currentInsights.advice }}</p><p v-else>{{ insightsLoading ? '正在结合本周风险整理建议…' : '当前暂无可引用的教育建议，可先查看案例库或刷新概览。' }}</p><small v-if="currentInsights" class="advice-updated">建议生成于 {{ formatInsightTime(currentInsights.generated_at_utc) }} · 统计数据实时更新</small><el-button class="advice-action" @click="openTrainingComposer()">据此生成培训 →</el-button><el-button class="advice-refresh" link :loading="insightsLoading" @click="loadInsights(true)">重新生成建议</el-button></section>
      </aside>
    </div>

    <section class="history-section"><div class="section-head"><div><span class="section-kicker">历史记录</span><h2>报告与培训档案</h2></div></div><div class="history-grid"><div class="surface history-list"><h3>安全报告 <small>{{ reports.length }}</small></h3><div v-if="reports.length"><div v-for="report in reports.slice(0, showAllReports ? undefined : 8)" :key="report.report_id" class="history-row"><div><strong>{{ reportDay(report.period_start_utc) }} — {{ reportDay(report.period_end_utc, true) }}</strong><small>{{ report.status === 'CONFIRMED' ? '已确认' : '草稿' }} · {{ report.statistics.total }} 条事件</small></div><div><el-button link @click="showReport(report)">查看</el-button><el-button v-if="report.pdf_url" link type="primary" @click="downloadPdf(report.report_id)">下载 PDF</el-button></div></div><el-button v-if="reports.length > 8" link @click="showAllReports = !showAllReports">{{ showAllReports ? '收起' : `查看全部 ${reports.length} 份报告` }}</el-button></div><p v-else class="muted">暂无历史报告</p></div><div class="surface history-list"><h3>培训记录 <small>{{ trainings.length }}</small></h3><div v-if="trainings.length"><div v-for="task in trainings.slice(0, showAllTraining ? undefined : 8)" :key="task.task_id" class="history-row"><div><strong>{{ task.title }}</strong><small>{{ task.status === 'PUBLISHED' ? '已发布' : '草稿' }} · 目标 {{ task.target_count }} 人</small></div><el-button link @click="showTraining(task)">查看</el-button></div><el-button v-if="trainings.length > 8" link @click="showAllTraining = !showAllTraining">{{ showAllTraining ? '收起' : `查看全部 ${trainings.length} 项任务` }}</el-button></div><p v-else class="muted">暂无培训记录</p></div></div></section>

    <el-dialog v-model="reportFormOpen" title="自定义安全报告时间" width="600px"><el-date-picker v-model="reportRange" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" /><p class="hint">统计区间含开始日及结束日；误报不计入。</p><template #footer><el-button @click="reportFormOpen = false">取消</el-button><el-button type="primary" :loading="busy" @click="makeReport">AI 生成报告草稿</el-button></template></el-dialog>

    <el-dialog v-model="reportDetailOpen" title="安全报告" width="880px" destroy-on-close><template v-if="selectedReport"><div class="dialog-meta"><strong>{{ reportDay(selectedReport.period_start_utc) }} — {{ reportDay(selectedReport.period_end_utc, true) }}</strong><el-tag :type="selectedReport.status === 'CONFIRMED' ? 'success' : 'warning'">{{ selectedReport.status === 'CONFIRMED' ? '已确认' : '草稿' }}</el-tag></div><div class="dialog-metrics"><span>事件 {{ selectedReport.statistics.total }}</span><span>重复 {{ selectedReport.statistics.repeat_occurrences }}</span></div><p>风险类型：{{ pairs(selectedReport.statistics.by_type) }}</p><p>区域：{{ pairs(selectedReport.statistics.by_zone) }}</p><el-form label-position="top"><el-form-item label="总结"><el-input v-model="selectedReport.content.summary" type="textarea" :rows="4" :disabled="selectedReport.status !== 'DRAFT'" /></el-form-item><el-form-item label="风险分析"><el-input v-model="selectedReport.content.risk_analysis" type="textarea" :rows="4" :disabled="selectedReport.status !== 'DRAFT'" /></el-form-item><el-form-item label="整改建议"><el-input v-model="selectedReport.content.remediation" type="textarea" :rows="4" :disabled="selectedReport.status !== 'DRAFT'" /></el-form-item></el-form><h4>规范引用</h4><p v-if="!selectedReport.citations.length" class="hint">当前规范库没有可引用依据</p><p v-for="citation in selectedReport.citations" :key="citation.chunk_id" class="citation">{{ citation.title }} · {{ citation.page_or_section }}</p><div class="dialog-actions"><template v-if="selectedReport.status === 'DRAFT'"><el-button :loading="busy" @click="saveReport">保存草稿</el-button><el-button type="primary" :loading="busy" @click="approveReport">确认并生成 PDF</el-button></template><el-button v-if="selectedReport.pdf_url" @click="downloadPdf(selectedReport.report_id)">下载 PDF</el-button><el-button type="danger" plain :disabled="busy" @click="removeReport">删除{{ selectedReport.status === 'DRAFT' ? '草稿' : '报告' }}</el-button></div></template></el-dialog>

    <el-dialog v-model="trainingFormOpen" title="生成培训方案" width="740px"><p class="hint">以已确认的安全报告和所选案例、规范为依据，AI 生成学习材料与题目草稿。</p><p v-if="!confirmedReports.length" class="inline-error">请先生成本周安全报告，在报告详情中确认后再创建培训。</p><el-form label-position="top"><el-form-item label="任务名称"><el-input v-model="trainingForm.title" placeholder="例如：本周危险区域作业安全教育" /></el-form-item><el-form-item label="本期安全报告"><el-select v-model="trainingForm.report_id" placeholder="选择已确认报告" style="width:100%"><el-option v-for="report in confirmedReports" :key="report.report_id" :label="`${reportDay(report.period_start_utc)} — ${reportDay(report.period_end_utc, true)}`" :value="report.report_id" /></el-select></el-form-item><el-form-item label="事故案例与规范"><el-select v-model="trainingForm.document_ids" multiple filterable remote :remote-method="loadDocumentOptions" placeholder="搜索资料，最多选择 10 份" style="width:100%"><el-option v-for="doc in allDocuments" :key="doc.document_id" :label="`${doc.document_type === 'STANDARD' ? '规范' : '案例'} · ${doc.title}`" :value="doc.document_id" /></el-select></el-form-item><div class="form-row"><el-form-item label="目标人数"><el-input-number v-model="trainingForm.target_count" :min="1" /></el-form-item><el-form-item label="题目数量"><el-input-number v-model="trainingForm.question_count" :min="1" :max="20" /></el-form-item><el-form-item label="及格分"><el-input-number v-model="trainingForm.pass_score" :min="0" :max="100" /></el-form-item></div></el-form><template #footer><el-button @click="trainingFormOpen = false">取消</el-button><el-button type="primary" :loading="busy" @click="makeTraining">AI 生成培训草稿</el-button></template></el-dialog>

    <el-dialog v-model="trainingDetailOpen" title="培训任务" width="920px" destroy-on-close><template v-if="selectedTraining"><div class="dialog-meta"><strong>{{ selectedTraining.title }}</strong><el-tag :type="selectedTraining.status === 'PUBLISHED' ? 'success' : 'warning'">{{ selectedTraining.status === 'PUBLISHED' ? '已发布' : '草稿' }}</el-tag></div><div class="source-list"><span>引用资料</span><p v-if="!selectedTraining.selected_documents.length" class="hint">未选取文档，培训仅使用已确认报告。</p><p v-for="source in selectedTraining.selected_documents" :key="source.document_id" class="citation">{{ source.title }} · {{ source.document_type === 'STANDARD' ? '规范' : '事故报告' }}</p></div><el-form label-position="top"><el-form-item label="任务名称"><el-input v-model="selectedTraining.title" :disabled="selectedTraining.status !== 'DRAFT'" /></el-form-item><div class="form-row"><el-form-item label="目标人数"><el-input-number v-model="selectedTraining.target_count" :min="1" :disabled="selectedTraining.status !== 'DRAFT'" /></el-form-item><el-form-item label="及格分"><el-input-number v-model="selectedTraining.pass_score" :min="0" :max="100" :disabled="selectedTraining.status !== 'DRAFT'" /></el-form-item></div><el-form-item label="学习材料"><el-input v-model="selectedTraining.material" type="textarea" :rows="7" :disabled="selectedTraining.status !== 'DRAFT'" /></el-form-item><div v-for="(question, index) in selectedTraining.questions" :key="index" class="question-editor"><strong>第 {{ index + 1 }} 题</strong><el-input v-model="question.stem" :disabled="selectedTraining.status !== 'DRAFT'" /><div v-for="(_, optionIndex) in question.options" :key="optionIndex" class="option-row"><span>{{ String.fromCharCode(65 + optionIndex) }}</span><el-input v-model="question.options[optionIndex]" :disabled="selectedTraining.status !== 'DRAFT'" /></div><el-radio-group v-model="question.answer" :disabled="selectedTraining.status !== 'DRAFT'"><el-radio v-for="(_, optionIndex) in question.options" :key="optionIndex" :value="optionIndex">{{ String.fromCharCode(65 + optionIndex) }} 正确</el-radio></el-radio-group><p v-if="question.evidence" class="hint">出题依据：{{ question.evidence }}</p></div></el-form><div v-if="selectedTraining.status === 'PUBLISHED'"><p>学习地址：<a :href="selectedTraining.public_url || '#'" target="_blank" rel="noopener">{{ selectedTraining.public_url }}</a></p><img v-if="qrObjectUrl" class="qr" :src="qrObjectUrl" alt="培训任务二维码" /><div v-if="trainingStats" class="stats"><span>完成 {{ trainingStats.completed_count }}/{{ trainingStats.target_count }}（{{ trainingStats.completion_rate }}%）</span><span>平均分 {{ trainingStats.average_score }}</span><span>及格率 {{ trainingStats.pass_rate }}%</span><el-table :data="trainingStats.submissions" size="small"><el-table-column prop="worker_id" label="工号" /><el-table-column prop="worker_name" label="姓名" /><el-table-column prop="score" label="分数" /><el-table-column label="是否及格"><template #default="scope">{{ scope.row.passed ? '是' : '否' }}</template></el-table-column></el-table></div></div><div class="dialog-actions"><template v-if="selectedTraining.status === 'DRAFT'"><el-button :loading="busy" @click="saveTraining">保存草稿</el-button><el-button type="primary" :loading="busy" @click="approveTraining">确认发布</el-button></template><el-button type="danger" plain :disabled="busy" @click="removeTraining">删除{{ selectedTraining.status === 'DRAFT' ? '草稿' : '任务' }}</el-button></div></template></el-dialog>

    <el-dialog v-model="documentDetailOpen" :title="selectedDocument?.title || '资料详情'" width="880px" destroy-on-close><template v-if="selectedDocument"><div class="dialog-meta"><span>{{ selectedDocument.document_type === 'STANDARD' ? '规范资料' : '事故案例' }} · {{ selectedDocument.document_date ? formatDay(selectedDocument.document_date) : '日期未注明' }}</span><el-button type="danger" link @click="removeDocument">停用文档</el-button></div><el-form label-position="top"><el-form-item label="事故日期 / 规范发布日期"><el-date-picker v-model="documentEdit.document_date" type="date" value-format="YYYY-MM-DD" clearable /></el-form-item><el-form-item label="风险标签（逗号分隔）"><el-input v-model="documentEdit.risk_tags" /></el-form-item><el-form-item label="来源"><el-input v-model="documentEdit.source_label" /></el-form-item><el-form-item label="AI 摘要（可人工修改）"><el-input v-model="documentEdit.summary" type="textarea" :rows="3" /></el-form-item><el-form-item v-if="selectedDocument.document_type === 'STANDARD'" label="规范有效性"><el-select v-model="documentEdit.validity_status"><el-option label="现行" value="CURRENT" /><el-option label="已废止或被替代" value="SUPERSEDED" /><el-option label="未核实" value="UNKNOWN" /></el-select></el-form-item><div class="dialog-actions"><el-button @click="saveDocument">保存元数据</el-button><el-button :loading="busy" @click="generateSummary">AI 生成摘要</el-button><el-button v-if="selectedDocument.document_type === 'ACCIDENT_REPORT'" @click="addToTraining(selectedDocument)">加入培训</el-button></div></el-form><template v-if="selectedDocument.document_type === 'ACCIDENT_REPORT'"><el-divider /><el-button :loading="busy" @click="generateCase">基于原文生成案例解读</el-button><div v-if="caseDetail" class="case-detail"><h4>事故经过</h4><p>{{ caseDetail.process }}</p><h4>原因</h4><p>{{ caseDetail.causes }}</p><h4>风险点</h4><p>{{ caseDetail.risks }}</p><h4>防范措施</h4><p>{{ caseDetail.prevention }}</p><h4>原文片段出处</h4><p v-for="item in caseDetail.citations" :key="item.chunk_id" class="citation">{{ item.title }} · {{ item.page_or_section }}</p></div></template><template v-else><el-divider /><h4>规范原文片段</h4><el-button v-if="!documentFragments.length" @click="loadFragments">查看原文</el-button><div v-for="fragment in documentFragments" :key="fragment.citation.chunk_id" class="fragment"><strong>{{ fragment.citation.page_or_section }}</strong><p>{{ fragment.content }}</p></div></template></template></el-dialog>

    <el-dialog v-model="uploadOpen" width="720px" class="upload-dialog" destroy-on-close>
      <template #header>
        <div class="upload-heading"><span class="upload-heading-icon"><el-icon><UploadFilled /></el-icon></span><div><h2>上传学习资料</h2><p>添加事故案例或规范文档，供学习中心检索与培训使用</p></div></div>
      </template>
      <div class="upload-content">
        <label class="upload-drop-zone" :class="{ 'has-file': file }" for="learning-file-upload" @dragover.prevent @drop.prevent="dropFile">
          <input :key="fileInputKey" id="learning-file-upload" class="upload-file-input" type="file" accept=".pdf,.docx,.md,.txt" @change="pickFile" />
          <span class="upload-drop-icon"><el-icon><UploadFilled /></el-icon></span>
          <strong>{{ file ? file.name : '将文档拖拽到这里，或点击选择文件' }}</strong>
          <span class="upload-drop-subtitle">{{ file ? `已选择 · ${formatFileSize(file.size)} · 点击可更换` : '支持 PDF、DOCX、Markdown 和 TXT 文档' }}</span>
          <span class="upload-select-button">{{ file ? '更换文件' : '选择文件' }}</span>
        </label>
        <div class="upload-divider"><strong>文档信息</strong><span>标题和类型必填，其余信息可后续补充</span></div>
        <el-form class="upload-form" label-position="top">
          <el-form-item label="文档标题" required><el-input v-model="uploadForm.title" placeholder="例如：某工地高处坠落事故调查报告" clearable /></el-form-item>
          <div class="upload-form-grid">
            <el-form-item label="资料类型" required><el-select v-model="uploadForm.document_type" style="width:100%"><el-option label="事故报告" value="ACCIDENT_REPORT" /><el-option label="规范文档" value="STANDARD" /></el-select></el-form-item>
            <el-form-item :label="uploadForm.document_type === 'STANDARD' ? '规范发布日期' : '事故发生日期'"><el-date-picker v-model="uploadForm.document_date" type="date" value-format="YYYY-MM-DD" placeholder="选择日期" clearable style="width:100%" /></el-form-item>
            <el-form-item label="风险标签"><el-input v-model="uploadForm.risk_tags" placeholder="如：高处作业，安全帽" /></el-form-item>
            <el-form-item label="资料来源"><el-input v-model="uploadForm.source_label" placeholder="如：事故调查报告、项目安全部" /></el-form-item>
          </div>
          <el-form-item label="摘要"><el-input v-model="uploadForm.summary" type="textarea" :rows="3" placeholder="选填；留空后由 AI 根据文档原文生成" /></el-form-item>
        </el-form>
      </div>
      <template #footer><div class="upload-footer"><span>上传后自动解析、分块并建立索引</span><div><el-button @click="uploadOpen = false">取消</el-button><el-button type="primary" :loading="busy" @click="submitUpload">上传并索引</el-button></div></div></template>
    </el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { UploadFilled } from '@element-plus/icons-vue'
import * as api from '@/api/learning'

const busy = ref(false), overviewLoading = ref(false), overviewError = ref(false), insightsLoading = ref(false)
const showAllReports = ref(false), showAllTraining = ref(false)
const overview = ref<api.WeeklyOverview | null>(null)
const insights = ref<api.WeeklyInsights | null>(null)
const reports = ref<api.Report[]>([]), selectedReport = ref<api.Report | null>(null)
const trainings = ref<api.Training[]>([]), selectedTraining = ref<api.Training | null>(null), trainingStats = ref<api.TrainingStatistics | null>(null)
const documents = ref<api.KnowledgeDocument[]>([]), allDocuments = ref<api.KnowledgeDocument[]>([]), documentTotal = ref(0), documentOffset = ref(0)
const selectedDocument = ref<api.KnowledgeDocument | null>(null), caseDetail = ref<api.CaseDetail | null>(null)
const documentFragments = ref<Array<{ content: string; citation: api.Citation }>>([])
const reportFormOpen = ref(false), reportDetailOpen = ref(false), trainingFormOpen = ref(false), trainingDetailOpen = ref(false), documentDetailOpen = ref(false), uploadOpen = ref(false)
const reportRange = ref<string[]>([]), documentRange = ref<string[]>([]), docQuery = ref(''), riskType = ref(''), docType = ref<'ACCIDENT_REPORT' | 'STANDARD'>('ACCIDENT_REPORT')
const documentEdit = ref({ document_date: '', risk_tags: '', source_label: '', summary: '', validity_status: 'UNKNOWN' })
const uploadForm = ref({ title: '', source_label: '', document_type: 'ACCIDENT_REPORT', document_date: '', risk_tags: '', summary: '' }), file = ref<File | null>(null)
const fileInputKey = ref(0)
const trainingForm = ref({ report_id: '', title: '', document_ids: [] as string[], target_count: 1, question_count: 5, pass_score: 80 })
const qrObjectUrl = ref('')
const timezone = import.meta.env.VITE_LEARNING_TIMEZONE || 'Asia/Shanghai'

const confirmedReports = computed(() => reports.value.filter(item => item.status === 'CONFIRMED'))
const currentInsights = computed(() => insights.value && overview.value && insights.value.period_start_utc === overview.value.period_start_utc && insights.value.risk_codes.join('|') === overview.value.main_risks.map(item => item.code).join('|') ? insights.value : null)
const weeklyTraining = computed(() => (overview.value?.weekly_tasks || []).map(weekly => {
  const task = trainings.value.find(item => item.task_id === weekly.task_id)
  return task ? { ...task, weekly } : null
}).filter((item): item is api.Training & { weekly: api.WeeklyOverview['weekly_tasks'][number] } => item !== null))
const availableRiskTags = computed(() => [...new Set([...documents.value.flatMap(doc => doc.risk_tags), ...allDocuments.value.flatMap(doc => doc.risk_tags), ...(overview.value?.main_risks.map(risk => risk.label) || [])])].filter(Boolean).sort())
const weekLabel = computed(() => overview.value ? `${formatDay(overview.value.period_start_utc)} — ${formatDay(overview.value.period_end_utc)}` : '本周风险与学习进度')
const pairs = (value: Record<string, number>) => Object.entries(value).map(([key, count]) => `${key} ${count}`).join('；') || '无'
function utcDate(value: string) { return new Date(/(?:Z|[+-]\d\d:\d\d)$/.test(value) ? value : `${value}Z`) }
function formatDay(value: string) { return utcDate(value).toLocaleDateString('zh-CN', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }) }
function formatInsightTime(value: string) { return utcDate(value).toLocaleString('zh-CN', { timeZone: timezone, month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) }
function formatFileSize(bytes: number) { return bytes >= 1024 * 1024 ? `${(bytes / (1024 * 1024)).toFixed(1)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB` }
function reportDay(value: string, exclusiveEnd = false) { return new Date(utcDate(value).getTime() - (exclusiveEnd ? 1 : 0)).toLocaleDateString('zh-CN', { timeZone: timezone }) }
async function downloadPdf(id: string) { const url = URL.createObjectURL(await api.downloadReport(id)); const link = document.createElement('a'); link.href = url; link.download = `safety-report-${id}.pdf`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 60000) }

async function loadOverview() { overviewLoading.value = true; overviewError.value = false; try { overview.value = await api.getWeeklyOverview() } catch { overviewError.value = true } finally { overviewLoading.value = false } }
async function loadInsights(force = false) { insightsLoading.value = true; try { insights.value = await api.getWeeklyInsights(force) } catch { if (!insights.value) ElMessage.warning('AI 建议暂时无法更新') } finally { insightsLoading.value = false } }
async function refresh() { await Promise.allSettled([loadOverview(), loadInsights(), loadDocuments(), api.listReports().then(value => { reports.value = value }), api.listTraining().then(value => { trainings.value = value })]) }
async function loadDocumentOptions(query: string) { const fetched = (await api.searchDocuments({ query, limit: 100 })).items; const selected = allDocuments.value.filter(doc => trainingForm.value.document_ids.includes(doc.document_id)); allDocuments.value = [...selected, ...fetched.filter(doc => !selected.some(item => item.document_id === doc.document_id))] }
async function loadDocuments() { const start = documentRange.value?.[0], end = documentRange.value?.[1]; const dateEnd = end ? new Date(new Date(`${end}T00:00:00+08:00`).getTime() + 86400000).toISOString() : undefined; const result = await api.searchDocuments({ query: docQuery.value || undefined, risk_type: riskType.value || undefined, document_type: docType.value, date_start: start ? `${start}T00:00:00+08:00` : undefined, date_end: dateEnd, offset: documentOffset.value }); documents.value = result.items; documentTotal.value = result.total }
function searchLibrary() { documentOffset.value = 0; void loadDocuments() }
function changeDocumentPage(page: number) { documentOffset.value = (page - 1) * 20; void loadDocuments() }
async function run(fn: () => Promise<void>) { busy.value = true; try { await fn() } catch (error) { const status = (error as { response?: { status: number } })?.response?.status; if (!status || status === 404) ElMessage.error(error instanceof Error ? error.message : '操作失败') } finally { busy.value = false } }

function showReport(report: api.Report) { selectedReport.value = JSON.parse(JSON.stringify(report)) as api.Report; reportDetailOpen.value = true }
function makeWeeklyReport() { if (!overview.value) return ElMessage.warning('本周概览尚未加载'); void run(async () => { const report = await api.createReport(overview.value!.period_start_utc, overview.value!.period_end_utc); reports.value = await api.listReports(); showReport(report); ElMessage.success('本周报告草稿已生成') }) }
function makeReport() { if (reportRange.value?.length !== 2) return ElMessage.warning('请选择时间段'); void run(async () => { const start = `${reportRange.value[0]}T00:00:00+08:00`; const end = new Date(new Date(`${reportRange.value[1]}T00:00:00+08:00`).getTime() + 86400000).toISOString(); const report = await api.createReport(start, end); reports.value = await api.listReports(); reportFormOpen.value = false; showReport(report); ElMessage.success('报告草稿已生成') }) }
function saveReport() { if (!selectedReport.value) return; void run(async () => { selectedReport.value = await api.editReport(selectedReport.value!.report_id, selectedReport.value!.content); reports.value = await api.listReports(); ElMessage.success('已保存') }) }
function approveReport() { if (!selectedReport.value) return; void run(async () => { await api.editReport(selectedReport.value!.report_id, selectedReport.value!.content); selectedReport.value = await api.confirmReport(selectedReport.value!.report_id); reports.value = await api.listReports(); ElMessage.success('报告已确认') }) }
async function removeReport() { const report = selectedReport.value; if (!report) return; if (trainings.value.some(task => task.report_id === report.report_id)) return ElMessage.warning('请先删除引用这份报告的培训任务'); try { await ElMessageBox.confirm(report.status === 'CONFIRMED' ? '报告和 PDF 将被永久删除，无法恢复。' : '删除后无法恢复这份报告草稿。', '确认删除报告', { type: 'warning', confirmButtonText: '确认删除' }) } catch { return } await run(async () => { await api.deleteReport(report.report_id); reportDetailOpen.value = false; selectedReport.value = null; if (trainingForm.value.report_id === report.report_id) trainingForm.value.report_id = ''; reports.value = await api.listReports(); ElMessage.success('报告已删除') }) }

function openDocument(doc: api.KnowledgeDocument) { selectedDocument.value = doc; caseDetail.value = null; documentFragments.value = []; documentEdit.value = { document_date: doc.document_date?.slice(0, 10) || '', risk_tags: doc.risk_tags.join(', '), source_label: doc.source_display, summary: doc.summary || '', validity_status: doc.validity_status }; documentDetailOpen.value = true }
function generateSummary() { if (!selectedDocument.value) return; void run(async () => { selectedDocument.value = await api.regenerateDocumentSummary(selectedDocument.value!.document_id); documentEdit.value.summary = selectedDocument.value.summary || ''; await loadDocuments(); ElMessage.success('摘要已生成') }) }
function loadFragments() { if (!selectedDocument.value) return; void run(async () => { documentFragments.value = (await api.getDocumentFragments(selectedDocument.value!.document_id)).items }) }
function saveDocument() { if (!selectedDocument.value) return; void run(async () => { const id = selectedDocument.value!.document_id; let updated = await api.updateDocumentMetadata(id, { document_date: documentEdit.value.document_date ? `${documentEdit.value.document_date}T00:00:00+08:00` : null, risk_tags: documentEdit.value.risk_tags.split(',').map(item => item.trim()).filter(Boolean), source_display: documentEdit.value.source_label, summary: documentEdit.value.summary }); if (selectedDocument.value!.document_type === 'STANDARD') updated = await api.updateStandardValidity(id, documentEdit.value.validity_status); selectedDocument.value = updated as api.KnowledgeDocument; await loadDocuments(); ElMessage.success('元数据已保存') }) }
function generateCase() { if (!selectedDocument.value) return; void run(async () => { caseDetail.value = await api.getCaseDetail(selectedDocument.value!.document_id) }) }
async function removeDocument() { if (!selectedDocument.value) return; try { await ElMessageBox.confirm('停用后文档将退出检索，历史引用仍保留。', '确认停用') } catch { return } await run(async () => { await api.retireDocument(selectedDocument.value!.document_id); documentDetailOpen.value = false; selectedDocument.value = null; await loadDocuments(); void loadInsights(true); ElMessage.success('文档已停用') }) }
function pickFile(event: Event) { file.value = (event.target as HTMLInputElement).files?.[0] || null; if (file.value && !uploadForm.value.title) uploadForm.value.title = file.value.name.replace(/\.[^.]+$/, '') }
function dropFile(event: DragEvent) { file.value = event.dataTransfer?.files?.[0] || null; if (file.value && !uploadForm.value.title) uploadForm.value.title = file.value.name.replace(/\.[^.]+$/, '') }
function submitUpload() { if (!file.value || !uploadForm.value.title) return ElMessage.warning('请选择文件并填写标题'); void run(async () => { await api.uploadDocument(file.value!, uploadForm.value); uploadOpen.value = false; uploadForm.value = { title: '', source_label: '', document_type: 'ACCIDENT_REPORT', document_date: '', risk_tags: '', summary: '' }; file.value = null; fileInputKey.value += 1; await loadDocuments(); void loadInsights(true); ElMessage.success('文档已上传') }) }

function openTrainingComposer(document?: api.KnowledgeDocument) {
  if (!trainingForm.value.report_id) trainingForm.value.report_id = confirmedReports.value[0]?.report_id || ''
  if (!trainingForm.value.title) trainingForm.value.title = overview.value?.main_risks[0] ? `本周${overview.value.main_risks[0].label}安全教育` : '本周施工安全教育'
  if (!trainingForm.value.document_ids.length) {
    const recommendations = currentInsights.value?.recommended_cases.slice(0, 2) || []
    trainingForm.value.document_ids = recommendations.map(item => item.document_id)
    allDocuments.value = [...recommendations.filter(item => !allDocuments.value.some(doc => doc.document_id === item.document_id)), ...allDocuments.value]
  }
  if (document && !trainingForm.value.document_ids.includes(document.document_id)) {
    if (trainingForm.value.document_ids.length >= 10) return ElMessage.warning('最多选择 10 份资料')
    trainingForm.value.document_ids.push(document.document_id)
    if (!allDocuments.value.some(item => item.document_id === document.document_id)) allDocuments.value = [document, ...allDocuments.value]
  }
  trainingFormOpen.value = true
  void loadDocumentOptions('').catch(() => ElMessage.warning('资料选项暂时无法加载'))
}
function addToTraining(document: api.KnowledgeDocument) { openTrainingComposer(document); ElMessage.success('已加入培训资料选择') }
function makeTraining() { if (!trainingForm.value.report_id || !trainingForm.value.title) return ElMessage.warning('请选择已确认报告并填写任务名称'); void run(async () => { const task = await api.createTraining(trainingForm.value); trainings.value = await api.listTraining(); trainingFormOpen.value = false; await loadOverview(); await showTraining(task); ElMessage.success('培训草稿已生成') }) }
async function showTraining(task: api.Training) { selectedTraining.value = JSON.parse(JSON.stringify(task)) as api.Training; trainingDetailOpen.value = true; trainingStats.value = null; if (qrObjectUrl.value) URL.revokeObjectURL(qrObjectUrl.value); qrObjectUrl.value = ''; if (task.status === 'PUBLISHED') { try { trainingStats.value = await api.getTrainingStats(task.task_id); qrObjectUrl.value = URL.createObjectURL(await api.getTrainingQr(task.task_id)) } catch { ElMessage.warning('任务已打开，完成情况或二维码暂时无法加载') } } }
function saveTraining() { if (!selectedTraining.value) return; void run(async () => { selectedTraining.value = await api.editTraining(selectedTraining.value!.task_id, selectedTraining.value!); trainings.value = await api.listTraining(); ElMessage.success('培训草稿已保存') }) }
function approveTraining() { if (!selectedTraining.value) return; void run(async () => { await api.editTraining(selectedTraining.value!.task_id, selectedTraining.value!); const task = await api.publishTraining(selectedTraining.value!.task_id); trainings.value = await api.listTraining(); await loadOverview(); await showTraining(task); ElMessage.success('培训任务已发布') }) }
async function removeTraining() { const task = selectedTraining.value; if (!task) return; const published = task.status === 'PUBLISHED'; const count = trainingStats.value?.completed_count; const message = published ? `删除后学习链接和二维码将失效，${count === undefined ? '已有答题及成绩记录' : `${count} 条答题及成绩记录`}也会永久删除。` : '删除后无法恢复这份培训草稿。'; try { await ElMessageBox.confirm(message, published ? '删除已发布任务' : '删除培训草稿', { type: 'warning', confirmButtonText: '确认删除' }) } catch { return } await run(async () => { await api.deleteTraining(task.task_id); trainingDetailOpen.value = false; selectedTraining.value = null; trainingStats.value = null; if (qrObjectUrl.value) URL.revokeObjectURL(qrObjectUrl.value); qrObjectUrl.value = ''; trainings.value = await api.listTraining(); await loadOverview(); ElMessage.success('培训任务已删除') }) }

onMounted(() => { void refresh() })
onUnmounted(() => { if (qrObjectUrl.value) URL.revokeObjectURL(qrObjectUrl.value) })
</script>

